_SCALAR(A,\'$.selling_price\'),\'\"\',\'\'),\',\',\'\') as float64) is null then cast(replace(replace(JSON_EXTRACT_SCALAR(A,\'$.mrp\'),\'\"\',\'\'),\',\',\'\') as float64) else safe_cast(replace(replace(JSON_EXTRACT_SCALAR(A,\'$.selling_price\'),\'\"\',\'\'),\',\',\'\') as float64) end) end cancel_sales, ifnull(cast(replace(JSON_EXTRACT_SCALAR(A,\'$.TAX\'),\'\"\',\'\') as float64),0) Tax, cast(replace(replace(JSON_EXTRACT_SCALAR(A,\'$.mrp\'),\'\"\',\'\'),\',\',\'\') as float64) as suborder_mrp, replace(JSON_EXTRACT_SCALAR(A,\'$.category\'),\'\"\',\'\') category, -1*(coalesce(cast(o.total_discount as float64)*(case when (case when safe_cast(replace(replace(JSON_EXTRACT_SCALAR(A,\'$.selling_price\'),\'\"\',\'\'),\',\',\'\') as float64) is null then cast(replace(replace(JSON_EXTRACT_SCALAR(A,\'$.mrp\'),\'\"\',\'\'),\',\',\'\') as float64) else safe_cast(replace(replace(JSON_EXTRACT_SCALAR(A,\'$.selling_price\'),\'\"\',\'\'),\',\',\'\') as float64) end )=0 then 1 else (case when safe_cast(replace(replace(JSON_EXTRACT_SCALAR(A,\'$.selling_price\'),\'\"\',\'\'),\',\',\'\') as float64) is null then cast(replace(replace(JSON_EXTRACT_SCALAR(A,\'$.mrp\'),\'\"\',\'\'),\',\',\'\') as float64) else safe_cast(replace(replace(JSON_EXTRACT_SCALAR(A,\'$.selling_price\'),\'\"\',\'\'),\',\',\'\') as float64) end ) end/case when sum(case when safe_cast(replace(replace(JSON_EXTRACT_SCALAR(A,\'$.selling_price\'),\'\"\',\'\'),\',\',\'\') as float64) is null then cast(replace(replace(JSON_EXTRACT_SCALAR(A,\'$.mrp\'),\'\"\',\'\'),\',\',\'\') as float64) else safe_cast(replace(replace(JSON_EXTRACT_SCALAR(A,\'$.selling_price\'),\'\"\',\'\'),\',\',\'\') as float64) end )over (partition by o.order_id) = 0 then 1 else sum(case when safe_cast(replace(replace(JSON_EXTRACT_SCALAR(A,\'$.selling_price\'),\'\"\',\'\'),\',\',\'\') as float64) is null then cast(replace(replace(JSON_EXTRACT_SCALAR(A,\'$.mrp\'),\'\"\',\'\'),\',\',\'\') as float64) else safe_cast(replace(replace(JSON_EXTRACT_SCALAR(A,\'$.selling_price\'),\'\"\',\'\'),\',\',\'\') as float64) end )over (partition by o.order_id) end ),0)) as discount , case when fo.order_id = o.order_id then \'New\' else \'Repeat\' end as new_customer_flag, case when date_trunc(safe_cast(left(fo.order_date,10) as date),month) = date_trunc(safe_cast(left(o.order_date,10) as date),month) then \'New\' else \'Repeat\' end as new_customer_flag_month, o.company_name as Warehouse_Name, cast(case when o.shipping_STATUS in (\'In Transit\', \'Shipment Created\') then date_diff(current_date(),date(left(o.ORDER_Date,10)),day) when o.shipping_STATUS in (\'Delivered\',\'Delivered To Origin\') then date_diff(date(left(o.shipping_Last_update_date,10)),date(left(o.ORDER_Date,10)),day) end as int64) as Days_in_Shipment, o.marketplace as Channel, o.payment_mode, o.import_date, o.last_update_date, o.pickup_pin_code pickup_pincode, ARRAY( SELECT part FROM UNNEST(SPLIT(replace(replace(JSON_EXTRACT_SCALAR(A,\'$.sku\'),\'\"\',\'\'),\'_\',\'-\'), \'-\')) AS part WHERE part != \'\' ) as sku_parts, row_number() over (partition by replace(JSON_EXTRACT_SCALAR(A,\'$.suborder_id\'),\'\"\',\'\') order by o.last_update_date desc) rw from orders o left join first_order fo on fo.contact_num = o.contact_num left join UNNEST(o.suborders) A ) s left join pick_up_dates pd on pd.Suborder_id = s.suborder_id left join intransit_dates id on id.Suborder_id = s.suborder_id left join delivery_dates dd on dd.Suborder_id = s.suborder_id left join (select * from (select sku as skucode ,Product_Name as name ,category_name as category ,product_image_url as image_url ,row_number() over (partition by SKU order by 1) rw from izf-wh.maplemonk.easyecom_izf_product_master where product_image_url is not null) where rw = 1 ) p on lower(master_sku) = lower(p.skucode) where s.rw = 1 ; create temp function FixEasyEcomDate(d STRING) AS ( CASE WHEN d IS NULL OR d IN (\'\', \'0000-00-00 00:00:00\', \'0000-00-00\') THEN NULL WHEN REGEXP_CONTAINS(d, r\'^\d{4}-\d{2}-\d{2} UTC\') THEN DA